#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *add_numbers(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    size_t n = (la > lb ? la : lb) + 2;
    char *out = malloc(n);
    if (!out) exit(1);
    out[n - 1] = '\0';
    size_t ia = la, ib = lb, io = n - 2;
    int carry = 0;
    while (ia || ib || carry) {
        int sum = carry;
        if (ia) sum += a[--ia] - '0';
        if (ib) sum += b[--ib] - '0';
        out[io--] = (char)('0' + sum % 10);
        carry = sum / 10;
    }
    memmove(out, out + io + 1, n - io - 1);
    return out;
}

